// Строки листа → payload вебхука. Пустые строки и строки без единого балла отбрасываем
// (Laravel вернул бы их как unmatched/empty_scores — незачем гонять).
const num = (v) => {
  const s = String(v ?? '').replace(',', '.').trim();
  if (s === '') return null;
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
};

const rows = [];
for (const item of $input.all()) {
  const j = item.json;
  const email = String(j['Email'] ?? j['email'] ?? j['Почта'] ?? '').trim();
  const course = String(j['Курс'] ?? j['course'] ?? j['Курс (slug)'] ?? '').trim();
  const clarity = num(j['Выразительность'] ?? j['score_clarity']);
  const letters = num(j['Дикция'] ?? j['score_letters']);
  const flow = num(j['Плавность'] ?? j['score_flow']);

  if (!email || !course) continue;
  if (clarity === null && letters === null && flow === null) continue;

  rows.push({
    email,
    course,
    score_clarity: clarity,
    score_letters: letters,
    score_flow: flow,
    row_ref: 'row ' + String(j.row_number ?? '?'),
  });
}

return [{ json: { rows } }];
